 sp=SPECS[p['id']];rows=[s for s in d['sentences'] if s['pattern_id']==p['id']];gap,answer,*wrong=sp['gap'];fill,answers,ar,en=sp['fill'];meaning,*meaning_answers=sp['meaning'];ctx,*ctx_answers=sp['context']
